import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


conv3d_cpp_decl = r"""
#include <torch/extension.h>
#include <cstdint>

torch::Tensor conv3d_cute_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""

conv3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>

#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------------
// cp.async helpers (4-byte copies). src-size = 0 zero-fills shared memory,
// which gives us bounds-checked staging with implicit zero-padding.
// ---------------------------------------------------------------------------
template <typename T>
__device__ __forceinline__ void my_cp_async_4B(T* smem_ptr, const T* gmem_ptr, bool pred)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  static_assert(sizeof(T) == 4, "my_cp_async_4B expects 4-byte elements");
  const unsigned saddr =
      static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
  const int src_size = pred ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
               :: "r"(saddr), "l"(gmem_ptr), "r"(src_size));
#else
  *smem_ptr = pred ? *gmem_ptr : T(0);
#endif
}

__device__ __forceinline__ void my_cp_async_commit()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}

template <int N>
__device__ __forceinline__ void my_cp_async_wait()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
#endif
}

template <typename T, int RK, int STAGES>
__global__ void __launch_bounds__(256, 2) conv3d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int Cin,
    int Cout,
    int D,
    int H,
    int Wd,
    int KD,
    int KH,
    int KW,
    int Dout,
    int Hout,
    int Wout,
    int stride,
    int padding,
    int dilation,
    int CinPerGroup,
    int CoutPerGroup)
{
  constexpr int BM      = 128;
  constexpr int BN      = 64;
  constexpr int Threads = 256;
  constexpr int TM      = 8;
  constexpr int TN      = 4;
  constexpr int RowThreads = BM / TM;
  constexpr int ColThreads = BN / TN;

  static_assert(BM % TM == 0, "BM must be divisible by TM");
  static_assert(BN % TN == 0, "BN must be divisible by TN");
  static_assert(RowThreads * ColThreads == Threads, "Invalid thread tile");

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;

  const int oc_tiles_per_group = (CoutPerGroup + BN - 1) / BN;
  const int group   = (int)blockIdx.y / oc_tiles_per_group;
  const int oc_tile = (int)blockIdx.y - group * oc_tiles_per_group;

  const int oc0 = group * CoutPerGroup + oc_tile * BN;
  const int ci0 = group * CinPerGroup;

  const int p0 = (int)blockIdx.x * BM;
  const int P  = Dout * Hout * Wout;

  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)CinPerGroup * KD * KH * KW;

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  const T* Xn = X + (int64_t)n * sXn;
  const T* Xg = Xn + (int64_t)ci0 * sXc;

  // Shared-memory tiles with a compile-time stage count: STAGES=2 gives the
  // classic double-buffered pipeline, while STAGES=1 (used when the whole
  // reduction dimension fits) keeps a single full-K tile resident so every
  // global element is staged exactly once. Both use dynamic shared memory.
  extern __shared__ __align__(16) unsigned char dyn_smem[];
  T* sX_raw = reinterpret_cast<T*>(dyn_smem);
  T* sW_raw = sX_raw + (size_t)STAGES * RK * BM;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BM>{}, Int<STAGES>{}),
          make_stride(Int<BM>{}, Int<1>{}, Int<RK * BM>{})
      )
  );
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_layout(
          make_shape(Int<RK>{}, Int<BN>{}, Int<STAGES>{}),
          make_stride(Int<BN>{}, Int<1>{}, Int<RK * BN>{})
      )
  );

  __shared__ int sOD[BM];
  __shared__ int sOH[BM];
  __shared__ int sOW[BM];
  __shared__ int sBD[BM];
  __shared__ int sBH[BM];
  __shared__ int sBW[BM];
  __shared__ int4 sK[RK];

  for (int i = tid; i < BM; i += Threads) {
    const int p = p0 + i;

    int od = 0;
    int oh = 0;
    int ow = 0;

    if (p < P) {
      const int HW = Hout * Wout;
      od = p / HW;
      const int rem = p - od * HW;
      oh = rem / Wout;
      ow = rem - oh * Wout;
    }

    sOD[i] = od;
    sOH[i] = oh;
    sOW[i] = ow;
    sBD[i] = od * stride - padding;
    sBH[i] = oh * stride - padding;
    sBW[i] = ow * stride - padding;
  }

  __syncthreads();

  Tensor acc = make_tensor<T>(make_shape(Int<TM>{}, Int<TN>{}));
  clear(acc);

  const int row0 = (tid % RowThreads) * TM;
  const int col0 = (tid / RowThreads) * TN;

  const int R = CinPerGroup * KD * KH * KW;
  const int numKTiles = (R + RK - 1) / RK;

  // Asynchronous staged loader for one K-tile into shared-memory buffer `buf`.
  auto load_tile = [&](int r0, int buf) {
    // Stage the per-r kernel-offset metadata (dilated kd/kh/kw and the
    // local input channel) in shared memory. The r -> (ci, kd, kh, kw)
    // decomposition is computed once per K-tile by RK threads instead of
    // being recomputed with expensive integer div/mod for every staged
    // element, which removes the integer-pipe bottleneck from the gather.
    if (tid < RK) {
      const int r = r0 + tid;
      int4 m = make_int4(0, 0, 0, 0);
      if (r < R) {
        const int kw = r % KW;
        int t = r / KW;
        const int kh = t % KH;
        t /= KH;
        const int kd = t % KD;
        const int ci = t / KD;
        m.x = kd * dilation;
        m.y = kh * dilation;
        m.z = kw * dilation;
        m.w = ci;
      }
      sK[tid] = m;
    }
    __syncthreads();
    // ---- Stage X tile: (RK, BM) ----
    for (int idx = tid; idx < RK * BM; idx += Threads) {
      const int rr = idx / BM;
      const int i  = idx - rr * BM;
      const int r  = r0 + rr;
      const T* gptr = X;
      bool pred = false;
      if (r < R && (p0 + i) < P) {
        const int4 m = sK[rr];
        const int id = sBD[i] + m.x;
        const int ih = sBH[i] + m.y;
        const int iw = sBW[i] + m.z;
        if (id >= 0 && id < D &&
            ih >= 0 && ih < H &&
            iw >= 0 && iw < Wd) {
          gptr = Xg + (int64_t)m.w * sXc
                    + (int64_t)id * sXd
                    + (int64_t)ih * sXh
                    + (int64_t)iw;
          pred = true;
        }
      }
      my_cp_async_4B(&sX(rr, i, buf), gptr, pred);
    }
    // ---- Stage W tile: (RK, BN) ----
    // The weight tensor [Cout, CinPerGroup, KD, KH, KW] is contiguous in
    // the reduction index r = ((ci * KD + kd) * KH + kh) * KW + kw, so the
    // in-group weight offset equals r exactly; no decomposition needed.
    for (int idx = tid; idx < RK * BN; idx += Threads) {
      const int j  = idx / RK;
      const int rr = idx - j * RK;
      const int r  = r0 + rr;
      const T* gptr = W;
      bool pred = false;
      const int local_oc = oc_tile * BN + j;
      if (r < R && local_oc < CoutPerGroup) {
        const int oc = group * CoutPerGroup + local_oc;
        gptr = W + (int64_t)oc * sWo + r;
        pred = true;
      }
      my_cp_async_4B(&sW(rr, j, buf), gptr, pred);
    }
  };

  // Prologue: issue loads for the first K-tile.
  load_tile(0, 0);
  my_cp_async_commit();
  // All threads must finish READING tile-0's sK metadata before
  // iteration 0's load_tile() overwrites the shared sK buffer (WAR race).
  // This does not affect the in-flight cp.async group: completion is
  // still governed by cp.async.wait_group in the main loop.
  __syncthreads();

  // Pipelined main loop: overlap next-tile loads with current-tile compute.
  for (int kt = 0; kt < numKTiles; ++kt) {
    const int r0  = kt * RK;
    const int cur = (STAGES == 1) ? 0 : (kt & 1);

    if constexpr (STAGES > 1) {
      if (kt + 1 < numKTiles) {
        load_tile((kt + 1) * RK, (kt + 1) & 1);
        my_cp_async_commit();
        my_cp_async_wait<1>();   // current tile ready, next may still be in flight
      } else {
        my_cp_async_wait<0>();   // drain remaining groups
      }
    } else {
      // Single-stage configuration: the trailing __syncthreads() of the
      // previous iteration guarantees compute finished before the next
      // tile overwrites the buffer (no overlap, correct for any R).
      if (kt > 0) {
        load_tile(r0, 0);
        my_cp_async_commit();
      }
      my_cp_async_wait<0>();
    }

    __syncthreads();

    static_assert(TM % 4 == 0, "TM must be a multiple of 4 for float4 loads");
    static_assert(TN == 4, "TN must be 4 for float4 loads");
    // Vectorized 128-bit shared-memory loads feeding the 8x4 register-
    // blocked outer product: 3 LDS.128 per rr instead of 12 scalar LDS,
    // which cuts shared-memory instruction count and bank conflicts.
    #pragma unroll 8
    for (int rr = 0; rr < RK; ++rr) {
      if (r0 + rr < R) {
        T xr[TM];
        #pragma unroll
        for (int q = 0; q < TM / 4; ++q) {
          const float4 xv =
              *reinterpret_cast<const float4*>(&sX(rr, row0 + 4 * q, cur));
          xr[4 * q + 0] = xv.x;
          xr[4 * q + 1] = xv.y;
          xr[4 * q + 2] = xv.z;
          xr[4 * q + 3] = xv.w;
        }
        const float4 wv =
            *reinterpret_cast<const float4*>(&sW(rr, col0, cur));
        const T wr[TN] = {wv.x, wv.y, wv.z, wv.w};
        #pragma unroll
        for (int tn = 0; tn < TN; ++tn) {
          #pragma unroll
          for (int tm = 0; tm < TM; ++tm) {
            acc(tm, tn) += xr[tm] * wr[tn];
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int tm = 0; tm < TM; ++tm) {
    const int i = row0 + tm;
    const int p = p0 + i;

    if (p >= P) {
      continue;
    }

    const int od = sOD[i];
    const int oh = sOH[i];
    const int ow = sOW[i];

    #pragma unroll
    for (int tn = 0; tn < TN; ++tn) {
      const int local_oc = oc_tile * BN + col0 + tn;

      if (local_oc >= CoutPerGroup) {
        continue;
      }

      const int oc = oc0 + col0 + tn;
      T value = acc(tm, tn);

      if (B != nullptr) {
        value += B[oc];
      }

      mY(oc, od, oh, ow) = value;
    }
  }
}

torch::Tensor conv3d_cute_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().is_cuda(), "bias must be a CUDA tensor");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 5, "x must have shape [N, C_in, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must have shape [C_out, C_in/groups, KD, KH, KW]");

  const int64_t N    = x.size(0);
  const int64_t Cin  = x.size(1);
  const int64_t D    = x.size(2);
  const int64_t H    = x.size(3);
  const int64_t Wd   = x.size(4);

  const int64_t Cout = w.size(0);
  const int64_t KD   = w.size(2);
  const int64_t KH   = w.size(3);
  const int64_t KW   = w.size(4);

  TORCH_CHECK(stride > 0, "stride must be positive");
  TORCH_CHECK(padding >= 0, "padding must be non-negative");
  TORCH_CHECK(dilation > 0, "dilation must be positive");
  TORCH_CHECK(groups > 0, "groups must be positive");

  TORCH_CHECK(Cin % groups == 0, "C_in must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "C_out must be divisible by groups");

  const int64_t CinPerGroup  = Cin / groups;
  const int64_t CoutPerGroup = Cout / groups;

  TORCH_CHECK(w.size(1) == CinPerGroup,
              "w.size(1) must equal C_in / groups");

  if (bias.has_value()) {
    TORCH_CHECK(bias.value().dim() == 1 && bias.value().size(0) == Cout,
                "bias must have shape [C_out]");
  }

  const int64_t Dout =
      (D + 2 * padding - dilation * (KD - 1) - 1) / stride + 1;
  const int64_t Hout =
      (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t Wout =
      (Wd + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0,
              "Computed output spatial dimensions must be positive");

  TORCH_CHECK(N <= 65535, "Batch size exceeds CUDA grid-z limit");
  TORCH_CHECK(Cin <= INT32_MAX && Cout <= INT32_MAX &&
              D <= INT32_MAX && H <= INT32_MAX && Wd <= INT32_MAX &&
              Dout <= INT32_MAX && Hout <= INT32_MAX && Wout <= INT32_MAX,
              "Tensor dimensions exceed 32-bit kernel indexing");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor bias_c;
  const float* bias_ptr = nullptr;
  if (bias.has_value()) {
    bias_c = bias.value().contiguous();
    bias_ptr = bias_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int BM      = 128;
  constexpr int BN      = 64;
  constexpr int Threads = 256;
  constexpr int RK_FULL = 81;
  constexpr int RK_PIPE = 8;
  const int64_t R = CinPerGroup * KD * KH * KW;
  const int smem_full = RK_FULL * (BM + BN) * (int)sizeof(float);
  const int smem_pipe = 2 * RK_PIPE * (BM + BN) * (int)sizeof(float);
  // Full-K single-stage variant: when the entire reduction dimension fits
  // in shared memory (R <= RK_FULL), every activation/weight element is
  // staged from global memory exactly once and the k-loop runs with no
  // pipeline turnover (no per-tile barriers or cp.async drains). It needs
  // >48KB of dynamic shared memory (opt-in) and is only used when two
  // CTAs per SM fit; otherwise the double-buffered pipelined variant runs.
  static const cudaError_t attr_err = [smem_full]() {
    return cudaFuncSetAttribute(
        conv3d_cute_kernel<float, 81, 1>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        smem_full);
  }();
  TORCH_CHECK(attr_err == cudaSuccess,
              "Failed to set max dynamic shared memory size: ",
              cudaGetErrorString(attr_err));
  static const int smem_per_sm = []() {
    int dev = 0;
    cudaGetDevice(&dev);
    int v = 0;
    cudaDeviceGetAttribute(&v, cudaDevAttrMaxSharedMemoryPerMultiprocessor, dev);
    return v;
  }();
  const bool full_k_ok =
      (R <= RK_FULL) && (2 * (smem_full + 6 * 1024) <= smem_per_sm);

  const int64_t P = Dout * Hout * Wout;
  const int64_t spatial_tiles = (P + BM - 1) / BM;
  const int64_t oc_tiles_per_group = (CoutPerGroup + BN - 1) / BN;

  TORCH_CHECK(spatial_tiles <= INT32_MAX,
              "Too many spatial tiles");
  TORCH_CHECK(groups * oc_tiles_per_group <= INT32_MAX,
              "Too many output-channel tiles");

  dim3 block(Threads);
  dim3 grid(
      (unsigned)spatial_tiles,
      (unsigned)(groups * oc_tiles_per_group),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (full_k_ok) {
    conv3d_cute_kernel<float, RK_FULL, 1><<<grid, block, smem_full, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        y.data_ptr<float>(),
        (int)Cin,
        (int)Cout,
        (int)D,
        (int)H,
        (int)Wd,
        (int)KD,
        (int)KH,
        (int)KW,
        (int)Dout,
        (int)Hout,
        (int)Wout,
        (int)stride,
        (int)padding,
        (int)dilation,
        (int)CinPerGroup,
        (int)CoutPerGroup
    );
  } else {
    conv3d_cute_kernel<float, RK_PIPE, 2><<<grid, block, smem_pipe, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        y.data_ptr<float>(),
        (int)Cin,
        (int)Cout,
        (int)D,
        (int)H,
        (int)Wd,
        (int)KD,
        (int)KH,
        (int)KW,
        (int)Dout,
        (int)Hout,
        (int)Wout,
        (int)stride,
        (int)padding,
        (int)dilation,
        (int)CinPerGroup,
        (int)CoutPerGroup
    );
  }

  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv3d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv3d_cute_ext = load_inline(
    name="conv3d_cute_tiled_ext",
    cpp_sources=conv3d_cpp_decl,
    cuda_sources=conv3d_cuda_src,
    functions=["conv3d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution using a single cooperative tiled CuTe CUDA kernel.

    nn.Conv3d is used only as a parameter container so that the state_dict and
    default parameter initialization remain compatible with the reference model.
    The forward computation is performed entirely by conv3d_cute_forward.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv3d = nn.Conv3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )
        self._ext = conv3d_cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_cute_forward(
            x,
            self.conv3d.weight,
            self.conv3d.bias,
            int(self.conv3d.stride[0]),
            int(self.conv3d.padding[0]),
            int(self.conv3d.dilation[0]),
            int(self.conv3d.groups),
        )

