        self.conv3d = nn.Conv3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )
        self._ext = conv3d_cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_cute_forward(
            x,
            self.conv3d.weight,
            self.conv3d.bias,
            int(self.conv3d.stride[0]),
            int(self.conv3d.padding[0]),
            int(self.conv3d.dilation[0]),
